import React, { useEffect, useMemo, useState } from 'react';
import { Button, Card, Drawer, Input, message, Space, Table, Tag, Typography, Col, Row, Select, Spin, Alert } from 'antd';
import dayjs from 'dayjs';
import { apiRequest, buildAuthHeaders } from '../api';

type SnapshotItem = {
  id: string;
  created_at: string;
  source: string;
  note?: string;
  tags?: string[];
};

type SnapshotDetail = SnapshotItem & {
  metrics: Record<string, any>;
};

const ArchitectMonitoring: React.FC = () => {
  const [minutes, setMinutes] = useState<number>(60);
  const [loading, setLoading] = useState<boolean>(false);
  const [top, setTop] = useState<any>({ top_kinds: [], top_bot_keys: [], top_message_types: [] });
  const [kindStats, setKindStats] = useState<any>({ items: [] });
  const headers = useMemo(() => buildAuthHeaders() as any, []);

  const loadData = async (m: number) => {
    setLoading(true);
    try {
      const t = await apiRequest(`/api/admin/soul/processor/top?minutes=${encodeURIComponent(String(m))}&limit=10`, 'GET', null, headers);
      const ks = await apiRequest(`/api/admin/soul/processor/kind_stats?minutes=${encodeURIComponent(String(m))}`, 'GET', null, headers);
      setTop(t || { top_kinds: [], top_bot_keys: [], top_message_types: [] });
      setKindStats(ks || { items: [] });
    } catch (e) {
      // noop, show error panel
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(minutes); }, []);

  const top3Kinds = (Array.isArray(top?.top_kinds) ? top.top_kinds : []).slice(0, 3);

  const kindColumns = [
    { title: 'Kind', dataIndex: 'kind', key: 'kind', render: (v: string) => <Typography.Text code>{v}</Typography.Text> },
    { title: 'Processed', dataIndex: 'processed', key: 'processed', width: 120 },
    { title: 'Skipped', dataIndex: 'skipped', key: 'skipped', width: 120 },
    { title: 'Total', dataIndex: 'total', key: 'total', width: 120 },
    { title: 'Error rate', dataIndex: 'error_rate', key: 'error_rate', render: (x: number) => <Tag color={x > 0.2 ? 'red' : x > 0.05 ? 'orange' : 'green'}>{(x * 100).toFixed(1)}%</Tag> },
    { title: 'p95 (ms)', dataIndex: 'e2e_p95_ms', key: 'e2e_p95_ms', width: 120 },
    { title: 'Limits', key: 'limits', render: (_: any, r: any) => (
      <Space size="small" wrap>
        <Tag>rps={r?.limits?.rps ?? '-'}</Tag>
        <Tag>conc={r?.limits?.max_concurrency ?? '-'}</Tag>
        <Tag>p95≤{r?.limits?.p95_budget_ms ?? '-'}</Tag>
        <Tag>err≤{r?.limits?.err_rate_max ?? '-'}</Tag>
      </Space>
    ) },
  ];

  return (
    <div style={{ padding: 'var(--sp-spacing-lg)' }}>
      <Row gutter={[16, 16]}>
        <Col span={24}>
          <Card title="Processor Monitor" extra={
            <Space size="small">
              <Typography.Text type="secondary">Window:</Typography.Text>
              <Select size="small" value={minutes} style={{ width: 120 }} onChange={(v) => { setMinutes(v); loadData(v); }} options={[
                { value: 10, label: '10 min' },
                { value: 30, label: '30 min' },
                { value: 60, label: '60 min' },
                { value: 180, label: '3 h' },
                { value: 1440, label: '24 h' },
              ]} />
            </Space>
          }>
            {loading ? <Spin /> : (
              <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                  <Card size="small" title="Top 3 event kinds">
                    {(top3Kinds?.length || 0) === 0 ? <Alert type="info" message="Нет данных" showIcon /> : (
                      <Space direction="vertical" style={{ width: '100%' }}>
                        {top3Kinds.map((it: any) => (
                          <Row key={String(it.kind)} justify="space-between" align="middle">
                            <Col><Typography.Text code>{it.kind}</Typography.Text></Col>
                            <Col><Tag color="blue">{it.count}</Tag></Col>
                          </Row>
                        ))}
                      </Space>
                    )}
                  </Card>
                </Col>
                <Col xs={24} md={12}>
                  <Card size="small" title="Per-kind stats">
                    <Table
                      rowKey={(r: any) => String(r.kind)}
                      columns={kindColumns as any}
                      dataSource={Array.isArray(kindStats?.items) ? kindStats.items : []}
                      size="small"
                      pagination={{ pageSize: 10 }}
                    />
                  </Card>
                </Col>
              </Row>
            )}
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default ArchitectMonitoring;


